function binarySearch(arr: number[], target: number): number {
  let left = 0;
  let right = arr.length;
  while (left < right) {
    const mid = (left + right) / 2;
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) left = mid;
    else right = mid;
  }
  return -1;
}
